-- Idempotent: re-running inserts nothing new (ON CONFLICT (slug) DO NOTHING).

-- Apply:

--   docker exec -i supabase-db psql -U postgres -d postgres < editorial-seed.sql

begin;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-what-kind-of-traveler-are-you',
  'What Kind of Traveler Are You?',
  'Your packing habits, your map habits and your 6 am alarm say more about you than the stamps in your passport.',
  'personality',
  'easy',
  'en',
  (select id from public.categories where slug = 'lifestyle'),
  '[{"id":"q1","question":"You land in a new city with a free afternoon. What''s the move?","options":[{"id":"a","text":"Wander until something interesting finds me.","personality_tags":["explorer"]},{"id":"b","text":"Check my list: the top three sights are already mapped.","personality_tags":["planner"]},{"id":"c","text":"Find a good café and watch the city go by.","personality_tags":["relaxer"]},{"id":"d","text":"Head straight for the museum or the old town.","personality_tags":["collector"]}],"explanation":null,"time_limit_seconds":30},{"id":"q2","question":"Your suitcase, 24 hours before departure:","options":[{"id":"a","text":"Half-packed; I''ll figure it out on the way.","personality_tags":["explorer"]},{"id":"b","text":"Packed, weighed, and the itinerary is printed.","personality_tags":["planner"]},{"id":"c","text":"A swimsuit and a book — what else is there?","personality_tags":["relaxer"]},{"id":"d","text":"With room reserved for whatever I bring back.","personality_tags":["collector"]}],"explanation":null,"time_limit_seconds":30},{"id":"q3","question":"Pick a way to spend a morning abroad:","options":[{"id":"a","text":"A hike to a viewpoint nobody recommended.","personality_tags":["explorer"]},{"id":"b","text":"The guided tour I booked weeks ago.","personality_tags":["planner"]},{"id":"c","text":"Breakfast at noon, then the beach.","personality_tags":["relaxer"]},{"id":"d","text":"A local market, then a cooking workshop.","personality_tags":["collector"]}],"explanation":null,"time_limit_seconds":30},{"id":"q4","question":"Your ideal souvenir is:","options":[{"id":"a","text":"A story I can''t quite explain.","personality_tags":["explorer"]},{"id":"b","text":"The thing I researched before the trip.","personality_tags":["planner"]},{"id":"c","text":"A tan and zero unread emails.","personality_tags":["relaxer"]},{"id":"d","text":"Something handmade by a local artisan.","personality_tags":["collector"]}],"explanation":null,"time_limit_seconds":30},{"id":"q5","question":"The restaurant strategy:","options":[{"id":"a","text":"The crowded place with no menu in sight.","personality_tags":["explorer"]},{"id":"b","text":"The reservation I made from the best-rated list.","personality_tags":["planner"]},{"id":"c","text":"Whatever''s closest to the pool.","personality_tags":["relaxer"]},{"id":"d","text":"The traditional spot where locals eat lunch.","personality_tags":["collector"]}],"explanation":null,"time_limit_seconds":30},{"id":"q6","question":"A rainy day ruins your plans. You:","options":[{"id":"a","text":"Go out anyway — wet streets, empty streets.","personality_tags":["explorer"]},{"id":"b","text":"Swap in the backup itinerary I already had.","personality_tags":["planner"]},{"id":"c","text":"Call it a spa day and order room service.","personality_tags":["relaxer"]},{"id":"d","text":"Museums were made for exactly this.","personality_tags":["collector"]}],"explanation":null,"time_limit_seconds":30},{"id":"q7","question":"How do you get around a new city?","options":[{"id":"a","text":"On foot, mostly lost, mostly happy.","personality_tags":["explorer"]},{"id":"b","text":"The transit pass, used efficiently.","personality_tags":["planner"]},{"id":"c","text":"A taxi to somewhere with a view.","personality_tags":["relaxer"]},{"id":"d","text":"The slow train — that''s where the country is.","personality_tags":["collector"]}],"explanation":null,"time_limit_seconds":30},{"id":"q8","question":"Your camera roll after a trip is mostly:","options":[{"id":"a","text":"Blurry shots of places I can''t name.","personality_tags":["explorer"]},{"id":"b","text":"Every landmark, in order.","personality_tags":["planner"]},{"id":"c","text":"Sunsets and plates of food.","personality_tags":["relaxer"]},{"id":"d","text":"Details: doors, tiles, street signs.","personality_tags":["collector"]}],"explanation":null,"time_limit_seconds":30}]'::jsonb,
  '[{"id":"r1","title":"The Explorer","description":"You travel by instinct and collect the places nobody else found. The best part of any trip is the part that wasn''t in the plan.","personality_tag":"explorer","background_theme":"forest"},{"id":"r2","title":"The Planner","description":"Your itineraries are legendary and your trips run like clockwork. You didn''t come all this way to stand in the wrong line.","personality_tag":"planner","background_theme":"stars"},{"id":"r3","title":"The Leisure Seeker","description":"A holiday is not a scavenger hunt. You measure a trip by how rested you feel on the flight home.","personality_tag":"relaxer","background_theme":"ocean"},{"id":"r4","title":"The Culture Collector","description":"You travel to understand, not just to see. Markets, museums and long lunches are your real souvenirs.","personality_tag":"collector","background_theme":"mystic"}]'::jsonb,
  array['personality quiz', 'travel', 'lifestyle', 'evergreen']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-que-tipo-de-viajero-eres',
  '¿Qué Tipo de Viajero Eres?',
  'Tu forma de empacar, tus mapas y tu alarma de las 6 am dicen más de ti que los sellos del pasaporte.',
  'personality',
  'easy',
  'es',
  (select id from public.categories where slug = 'lifestyle'),
  '[{"id":"q1","question":"Llegas a una ciudad nueva con una tarde libre. ¿Qué haces?","options":[{"id":"a","text":"Caminar sin rumbo hasta que algo me sorprenda.","personality_tags":["explorador"]},{"id":"b","text":"Revisar mi lista: los tres imperdibles ya están marcados.","personality_tags":["planificador"]},{"id":"c","text":"Buscar un buen café y mirar la ciudad pasar.","personality_tags":["relajado"]},{"id":"d","text":"Ir directo al museo o al casco antiguo.","personality_tags":["coleccionista"]}],"explanation":null,"time_limit_seconds":30},{"id":"q2","question":"Tu maleta, 24 horas antes de salir:","options":[{"id":"a","text":"A medio hacer; el resto se resuelve en el camino.","personality_tags":["explorador"]},{"id":"b","text":"Lista, pesada y con el itinerario impreso.","personality_tags":["planificador"]},{"id":"c","text":"Traje de baño y un libro, ¿qué más se necesita?","personality_tags":["relajado"]},{"id":"d","text":"Con espacio reservado para lo que traiga de vuelta.","personality_tags":["coleccionista"]}],"explanation":null,"time_limit_seconds":30},{"id":"q3","question":"Elige cómo pasar una mañana en el extranjero:","options":[{"id":"a","text":"Una caminata a un mirador que nadie recomendó.","personality_tags":["explorador"]},{"id":"b","text":"El tour guiado que reservé hace semanas.","personality_tags":["planificador"]},{"id":"c","text":"Desayunar tarde y después la playa.","personality_tags":["relajado"]},{"id":"d","text":"Un mercado local y luego un taller de cocina.","personality_tags":["coleccionista"]}],"explanation":null,"time_limit_seconds":30},{"id":"q4","question":"Tu recuerdo ideal de un viaje es:","options":[{"id":"a","text":"Una historia que no puedo explicar del todo.","personality_tags":["explorador"]},{"id":"b","text":"Lo que investigué antes de viajar.","personality_tags":["planificador"]},{"id":"c","text":"Un bronceado y cero correos sin leer.","personality_tags":["relajado"]},{"id":"d","text":"Algo hecho a mano por un artesano local.","personality_tags":["coleccionista"]}],"explanation":null,"time_limit_seconds":30},{"id":"q5","question":"¿Cómo eliges restaurante en un viaje?","options":[{"id":"a","text":"El lugar lleno donde no hay menú a la vista.","personality_tags":["explorador"]},{"id":"b","text":"La reserva que hice de la lista de mejor valorados.","personality_tags":["planificador"]},{"id":"c","text":"El que quede más cerca de la piscina.","personality_tags":["relajado"]},{"id":"d","text":"El tradicional donde almuerza la gente del barrio.","personality_tags":["coleccionista"]}],"explanation":null,"time_limit_seconds":30},{"id":"q6","question":"Un día de lluvia arruina tus planes. Tú:","options":[{"id":"a","text":"Salgo igual: calles mojadas, calles vacías.","personality_tags":["explorador"]},{"id":"b","text":"Activo el plan B que ya tenía pensado.","personality_tags":["planificador"]},{"id":"c","text":"Lo declaro día de descanso y pido comida a la habitación.","personality_tags":["relajado"]},{"id":"d","text":"Los museos se inventaron para esto.","personality_tags":["coleccionista"]}],"explanation":null,"time_limit_seconds":30},{"id":"q7","question":"¿Cómo te mueves por una ciudad nueva?","options":[{"id":"a","text":"A pie, medio perdido, medio feliz.","personality_tags":["explorador"]},{"id":"b","text":"Con el pase de transporte, usado a fondo.","personality_tags":["planificador"]},{"id":"c","text":"En taxi hasta algún lugar con vista.","personality_tags":["relajado"]},{"id":"d","text":"En el tren lento: ahí está el país de verdad.","personality_tags":["coleccionista"]}],"explanation":null,"time_limit_seconds":30},{"id":"q8","question":"Tu galería de fotos después del viaje es sobre todo:","options":[{"id":"a","text":"Fotos borrosas de lugares que no sé nombrar.","personality_tags":["explorador"]},{"id":"b","text":"Todos los monumentos, en orden.","personality_tags":["planificador"]},{"id":"c","text":"Atardeceres y platos de comida.","personality_tags":["relajado"]},{"id":"d","text":"Detalles: puertas, azulejos, letreros.","personality_tags":["coleccionista"]}],"explanation":null,"time_limit_seconds":30}]'::jsonb,
  '[{"id":"r1","title":"El Explorador","description":"Viajas por instinto y coleccionas los lugares que nadie más encontró. La mejor parte del viaje es la que no estaba en el plan.","personality_tag":"explorador","background_theme":"forest"},{"id":"r2","title":"El Planificador","description":"Tus itinerarios son legendarios y tus viajes funcionan como reloj. No viniste hasta aquí para hacer la fila equivocada.","personality_tag":"planificador","background_theme":"stars"},{"id":"r3","title":"El Buscador de Calma","description":"Las vacaciones no son una búsqueda del tesoro. Mides un viaje por lo descansado que vuelves a casa.","personality_tag":"relajado","background_theme":"ocean"},{"id":"r4","title":"El Coleccionista de Culturas","description":"Viajas para entender, no solo para ver. Los mercados, los museos y las sobremesas largas son tus verdaderos recuerdos.","personality_tag":"coleccionista","background_theme":"mystic"}]'::jsonb,
  array['personality quiz', 'viajes', 'estilo de vida', 'evergreen']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-what-kind-of-friend-are-you',
  'What Kind of Friend Are You?',
  'Every group chat has roles nobody voted on. Eight questions to find out which one is quietly yours.',
  'personality',
  'easy',
  'en',
  (select id from public.categories where slug = 'relationships'),
  '[{"id":"q1","question":"A friend texts ''you free tonight?'' at 11 pm. You:","options":[{"id":"a","text":"Throw on a jacket — they wouldn''t ask if it wasn''t important.","personality_tags":["loyal"]},{"id":"b","text":"Already dressed. Where are we going?","personality_tags":["spark"]},{"id":"c","text":"Call back: ''Talk to me first. What''s going on?''","personality_tags":["confidant"]},{"id":"d","text":"Ask who''s coming and where, then book the table.","personality_tags":["organizer"]}],"explanation":null,"time_limit_seconds":30},{"id":"q2","question":"In the group chat, you''re the one who:","options":[{"id":"a","text":"Shows up to every plan, even the bad ones.","personality_tags":["loyal"]},{"id":"b","text":"Drops the meme that derails the whole thread.","personality_tags":["spark"]},{"id":"c","text":"Takes it private when things get real.","personality_tags":["confidant"]},{"id":"d","text":"Actually sets the date, the time and the place.","personality_tags":["organizer"]}],"explanation":null,"time_limit_seconds":30},{"id":"q3","question":"A friend shares big news. Your first move:","options":[{"id":"a","text":"Be the first to defend it if anyone doubts them.","personality_tags":["loyal"]},{"id":"b","text":"Pop something fizzy, obviously.","personality_tags":["spark"]},{"id":"c","text":"Ask the question nobody else thought to ask.","personality_tags":["confidant"]},{"id":"d","text":"Start planning the celebration dinner.","personality_tags":["organizer"]}],"explanation":null,"time_limit_seconds":30},{"id":"q4","question":"A friend is moving house. You:","options":[{"id":"a","text":"Show up at 8 am with coffee and don''t leave till it''s done.","personality_tags":["loyal"]},{"id":"b","text":"Bring the playlist that makes lifting boxes bearable.","personality_tags":["spark"]},{"id":"c","text":"Keep them company in the car between trips.","personality_tags":["confidant"]},{"id":"d","text":"Label the boxes and manage the schedule.","personality_tags":["organizer"]}],"explanation":null,"time_limit_seconds":30},{"id":"q5","question":"The group argues about where to go. You:","options":[{"id":"a","text":"Side with whoever needs the win that week.","personality_tags":["loyal"]},{"id":"b","text":"Suggest something so unexpected everyone forgets the fight.","personality_tags":["spark"]},{"id":"c","text":"Smooth it over and keep everyone talking.","personality_tags":["confidant"]},{"id":"d","text":"Send a poll and end the debate.","personality_tags":["organizer"]}],"explanation":null,"time_limit_seconds":30},{"id":"q6","question":"Your friend had a terrible day. You:","options":[{"id":"a","text":"Arrive unannounced with dinner.","personality_tags":["loyal"]},{"id":"b","text":"Drag them out — misery hates good company.","personality_tags":["spark"]},{"id":"c","text":"Let them vent for as long as it takes.","personality_tags":["confidant"]},{"id":"d","text":"Quietly handle the errands they can''t deal with.","personality_tags":["organizer"]}],"explanation":null,"time_limit_seconds":30},{"id":"q7","question":"Your signature as a friend is:","options":[{"id":"a","text":"Years later, still there.","personality_tags":["loyal"]},{"id":"b","text":"The story everyone retells at parties.","personality_tags":["spark"]},{"id":"c","text":"The secrets that stay secret.","personality_tags":["confidant"]},{"id":"d","text":"The trip that only happened because of you.","personality_tags":["organizer"]}],"explanation":null,"time_limit_seconds":30},{"id":"q8","question":"Birthdays, in your world, mean:","options":[{"id":"a","text":"Never forgetting one. Ever.","personality_tags":["loyal"]},{"id":"b","text":"The surprise that tops last year''s.","personality_tags":["spark"]},{"id":"c","text":"A long call that goes past midnight.","personality_tags":["confidant"]},{"id":"d","text":"A hidden checklist that includes the cake order.","personality_tags":["organizer"]}],"explanation":null,"time_limit_seconds":30}]'::jsonb,
  '[{"id":"r1","title":"The Loyal One","description":"You are the friend who stays. Long after the party ends, you''re the one still there, still helping.","personality_tag":"loyal","background_theme":"forest"},{"id":"r2","title":"The Spark","description":"You are the reason the night got interesting. Every group needs someone who says ''what if we just...'' — that''s you.","personality_tag":"spark","background_theme":"fire"},{"id":"r3","title":"The Confidant","description":"People tell you things they''ve told no one else. You listen without judging and keep secrets like a vault.","personality_tag":"confidant","background_theme":"stars"},{"id":"r4","title":"The Organizer","description":"Group chats would die without you. You''re the reason the trip actually happened and the table actually got booked.","personality_tag":"organizer","background_theme":"ice"}]'::jsonb,
  array['personality quiz', 'friendship', 'relationships', 'evergreen']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-que-tipo-de-amigo-eres',
  '¿Qué Tipo de Amigo Eres?',
  'Todo grupo tiene roles que nadie votó. Ocho preguntas para descubrir cuál es, discretamente, el tuyo.',
  'personality',
  'easy',
  'es',
  (select id from public.categories where slug = 'relationships'),
  '[{"id":"q1","question":"Un amigo escribe ''¿estás libre esta noche?'' a las 11 pm. Tú:","options":[{"id":"a","text":"Me pongo la chaqueta: no preguntaría si no fuera importante.","personality_tags":["leal"]},{"id":"b","text":"Ya estoy listo. ¿A dónde vamos?","personality_tags":["chispa"]},{"id":"c","text":"Devuelvo la llamada: ''Cuéntame primero, ¿qué pasa?''","personality_tags":["confidente"]},{"id":"d","text":"Pregunto quién va y a dónde, y reservo la mesa.","personality_tags":["organizador"]}],"explanation":null,"time_limit_seconds":30},{"id":"q2","question":"En el chat del grupo, tú eres quien:","options":[{"id":"a","text":"Aparece en cada plan, incluso en los malos.","personality_tags":["leal"]},{"id":"b","text":"Suelta el meme que descarrila la conversación.","personality_tags":["chispa"]},{"id":"c","text":"Lleva a privado lo que se pone serio.","personality_tags":["confidente"]},{"id":"d","text":"Define la fecha, la hora y el lugar.","personality_tags":["organizador"]}],"explanation":null,"time_limit_seconds":30},{"id":"q3","question":"Un amigo te cuenta una gran noticia. Tu primer movimiento:","options":[{"id":"a","text":"Ser el primero en defenderlo si alguien duda.","personality_tags":["leal"]},{"id":"b","text":"Abrir algo con burbujas, obviamente.","personality_tags":["chispa"]},{"id":"c","text":"Hacer la pregunta que nadie más pensó.","personality_tags":["confidente"]},{"id":"d","text":"Empezar a organizar la cena de celebración.","personality_tags":["organizador"]}],"explanation":null,"time_limit_seconds":30},{"id":"q4","question":"Un amigo se muda de casa. Tú:","options":[{"id":"a","text":"Llego a las 8 am con café y no me voy hasta terminar.","personality_tags":["leal"]},{"id":"b","text":"Llevo la música que hace tolerable cargar cajas.","personality_tags":["chispa"]},{"id":"c","text":"Le hago compañía en el auto entre viaje y viaje.","personality_tags":["confidente"]},{"id":"d","text":"Etiqueto las cajas y controlo los horarios.","personality_tags":["organizador"]}],"explanation":null,"time_limit_seconds":30},{"id":"q5","question":"El grupo discute a dónde ir. Tú:","options":[{"id":"a","text":"Apoyo a quien más necesita ganar esa semana.","personality_tags":["leal"]},{"id":"b","text":"Propongo algo tan inesperado que todos olvidan la pelea.","personality_tags":["chispa"]},{"id":"c","text":"Calmo los ánimos y mantengo a todos hablando.","personality_tags":["confidente"]},{"id":"d","text":"Mando una encuesta y cierro el debate.","personality_tags":["organizador"]}],"explanation":null,"time_limit_seconds":30},{"id":"q6","question":"Tu amigo tuvo un día horrible. Tú:","options":[{"id":"a","text":"Aparezco sin avisar y con la cena.","personality_tags":["leal"]},{"id":"b","text":"Lo saco a la calle: la pena odia la buena compañía.","personality_tags":["chispa"]},{"id":"c","text":"Lo escucho desahogarse el tiempo que necesite.","personality_tags":["confidente"]},{"id":"d","text":"Resuelvo en silencio los pendientes que lo agobian.","personality_tags":["organizador"]}],"explanation":null,"time_limit_seconds":30},{"id":"q7","question":"Tu sello como amigo es:","options":[{"id":"a","text":"Años después, seguir ahí.","personality_tags":["leal"]},{"id":"b","text":"La anécdota que todos repiten en las fiestas.","personality_tags":["chispa"]},{"id":"c","text":"Los secretos que nunca salen de ti.","personality_tags":["confidente"]},{"id":"d","text":"El viaje que solo sucedió gracias a ti.","personality_tags":["organizador"]}],"explanation":null,"time_limit_seconds":30},{"id":"q8","question":"Los cumpleaños, en tu mundo, significan:","options":[{"id":"a","text":"No olvidar ni uno solo. Jamás.","personality_tags":["leal"]},{"id":"b","text":"La sorpresa que supera a la del año pasado.","personality_tags":["chispa"]},{"id":"c","text":"Una llamada larga que pasa de medianoche.","personality_tags":["confidente"]},{"id":"d","text":"Una lista secreta que incluye encargar el pastel.","personality_tags":["organizador"]}],"explanation":null,"time_limit_seconds":30}]'::jsonb,
  '[{"id":"r1","title":"El Amigo Leal","description":"Eres el amigo que se queda. Mucho después de que acaba la fiesta, sigues ahí, ayudando.","personality_tag":"leal","background_theme":"forest"},{"id":"r2","title":"La Chispa del Grupo","description":"Eres la razón por la que la noche se puso interesante. Todo grupo necesita a quien dice ''¿y si...?'': ese eres tú.","personality_tag":"chispa","background_theme":"fire"},{"id":"r3","title":"El Confidente","description":"La gente te cuenta lo que no le cuenta a nadie. Escuchas sin juzgar y guardas secretos como una bóveda.","personality_tag":"confidente","background_theme":"stars"},{"id":"r4","title":"El Organizador","description":"Sin ti, los chats de grupo morirían. Eres la razón por la que el viaje sucedió y la mesa se reservó.","personality_tag":"organizador","background_theme":"ice"}]'::jsonb,
  array['personality quiz', 'amistad', 'relaciones', 'evergreen']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-what-is-your-work-style',
  'What Is Your Work Style?',
  'Deadlines, inboxes and Monday meetings reveal more about you than any job title. Find your default mode.',
  'personality',
  'easy',
  'en',
  (select id from public.categories where slug = 'lifestyle'),
  '[{"id":"q1","question":"A new project lands on your desk Monday morning. You:","options":[{"id":"a","text":"Map the whole thing before touching a single task.","personality_tags":["strategist"]},{"id":"b","text":"Start on the first task before the kickoff ends.","personality_tags":["sprinter"]},{"id":"c","text":"Ask who''s on board and what they need from me.","personality_tags":["collaborator"]},{"id":"d","text":"Read the brief twice, then write down my questions.","personality_tags":["perfectionist"]}],"explanation":null,"time_limit_seconds":30},{"id":"q2","question":"The deadline is Friday. On Wednesday you are:","options":[{"id":"a","text":"On schedule — the plan already accounted for this.","personality_tags":["strategist"]},{"id":"b","text":"In full sprint mode; this is when I do my best work.","personality_tags":["sprinter"]},{"id":"c","text":"Checking in with everyone to unblock them.","personality_tags":["collaborator"]},{"id":"d","text":"Polishing the third draft.","personality_tags":["perfectionist"]}],"explanation":null,"time_limit_seconds":30},{"id":"q3","question":"Meetings are:","options":[{"id":"a","text":"Useful only with an agenda and a decision.","personality_tags":["strategist"]},{"id":"b","text":"Time I''d rather spend doing the actual work.","personality_tags":["sprinter"]},{"id":"c","text":"Where the good ideas actually happen.","personality_tags":["collaborator"]},{"id":"d","text":"A chance to catch what everyone else missed.","personality_tags":["perfectionist"]}],"explanation":null,"time_limit_seconds":30},{"id":"q4","question":"Your inbox at 6 pm:","options":[{"id":"a","text":"Sorted by priority for tomorrow.","personality_tags":["strategist"]},{"id":"b","text":"Whatever''s left can wait.","personality_tags":["sprinter"]},{"id":"c","text":"Zero unread — people are waiting on me.","personality_tags":["collaborator"]},{"id":"d","text":"Answered, with every detail confirmed.","personality_tags":["perfectionist"]}],"explanation":null,"time_limit_seconds":30},{"id":"q5","question":"A teammate''s plan has a flaw. You:","options":[{"id":"a","text":"Show how it breaks the bigger picture.","personality_tags":["strategist"]},{"id":"b","text":"Fix it on the fly and keep moving.","personality_tags":["sprinter"]},{"id":"c","text":"Ask questions until they spot it themselves.","personality_tags":["collaborator"]},{"id":"d","text":"Send annotated notes with the correction.","personality_tags":["perfectionist"]}],"explanation":null,"time_limit_seconds":30},{"id":"q6","question":"Your desk says:","options":[{"id":"a","text":"Organized by project phase.","personality_tags":["strategist"]},{"id":"b","text":"Creative chaos with a system only I understand.","personality_tags":["sprinter"]},{"id":"c","text":"Covered in notes from other people''s requests.","personality_tags":["collaborator"]},{"id":"d","text":"Everything aligned, nothing out of place.","personality_tags":["perfectionist"]}],"explanation":null,"time_limit_seconds":30},{"id":"q7","question":"The praise you actually enjoy:","options":[{"id":"a","text":"''That plan saved us a month.''","personality_tags":["strategist"]},{"id":"b","text":"''How did you finish that already?''","personality_tags":["sprinter"]},{"id":"c","text":"''The team works better when you''re in it.''","personality_tags":["collaborator"]},{"id":"d","text":"''Nobody checks your work twice.''","personality_tags":["perfectionist"]}],"explanation":null,"time_limit_seconds":30},{"id":"q8","question":"Friday afternoon, project shipped. You:","options":[{"id":"a","text":"Review what the plan got right and wrong.","personality_tags":["strategist"]},{"id":"b","text":"Already thinking about Monday''s sprint.","personality_tags":["sprinter"]},{"id":"c","text":"Take the team out to celebrate.","personality_tags":["collaborator"]},{"id":"d","text":"One last pass on the documentation.","personality_tags":["perfectionist"]}],"explanation":null,"time_limit_seconds":30}]'::jsonb,
  '[{"id":"r1","title":"The Strategist","description":"You see the whole board while others see the next move. Your plans save more time than any sprint ever could.","personality_tag":"strategist","background_theme":"stars"},{"id":"r2","title":"The Sprinter","description":"Deadlines are your fuel. While others are still planning, you''ve already shipped and moved on.","personality_tag":"sprinter","background_theme":"fire"},{"id":"r3","title":"The Collaborator","description":"You make teams work. Meetings get shorter, blockers disappear and everyone does better work when you''re around.","personality_tag":"collaborator","background_theme":"ocean"},{"id":"r4","title":"The Perfectionist","description":"Your work doesn''t come back with corrections. The details everyone else misses are exactly the ones you catch.","personality_tag":"perfectionist","background_theme":"ice"}]'::jsonb,
  array['personality quiz', 'work', 'lifestyle', 'evergreen']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-cual-es-tu-estilo-de-trabajo',
  '¿Cuál Es Tu Estilo de Trabajo?',
  'Las fechas límite, la bandeja de entrada y las reuniones del lunes dicen más de ti que tu cargo. Encuentra tu modo por defecto.',
  'personality',
  'easy',
  'es',
  (select id from public.categories where slug = 'lifestyle'),
  '[{"id":"q1","question":"Un proyecto nuevo llega a tu escritorio el lunes. Tú:","options":[{"id":"a","text":"Dibujo el plan completo antes de tocar una tarea.","personality_tags":["estratega"]},{"id":"b","text":"Arranco con la primera tarea antes de que acabe la reunión.","personality_tags":["velocista"]},{"id":"c","text":"Pregunto quién participa y qué necesita de mí.","personality_tags":["colaborador"]},{"id":"d","text":"Leo el brief dos veces y anoto mis dudas.","personality_tags":["perfeccionista"]}],"explanation":null,"time_limit_seconds":30},{"id":"q2","question":"La entrega es el viernes. El miércoles estás:","options":[{"id":"a","text":"Al día: el plan ya contemplaba este momento.","personality_tags":["estratega"]},{"id":"b","text":"En plena racha; es cuando mejor trabajo.","personality_tags":["velocista"]},{"id":"c","text":"Revisando con cada uno para destrabar lo que falta.","personality_tags":["colaborador"]},{"id":"d","text":"Puliendo la tercera versión.","personality_tags":["perfeccionista"]}],"explanation":null,"time_limit_seconds":30},{"id":"q3","question":"Las reuniones son:","options":[{"id":"a","text":"Útiles solo con agenda y una decisión clara.","personality_tags":["estratega"]},{"id":"b","text":"Tiempo que preferiría dedicar al trabajo real.","personality_tags":["velocista"]},{"id":"c","text":"Donde de verdad salen las buenas ideas.","personality_tags":["colaborador"]},{"id":"d","text":"La ocasión de pillar lo que se le pasó a todos.","personality_tags":["perfeccionista"]}],"explanation":null,"time_limit_seconds":30},{"id":"q4","question":"Tu bandeja de entrada a las 6 pm:","options":[{"id":"a","text":"Ordenada por prioridad para mañana.","personality_tags":["estratega"]},{"id":"b","text":"Lo que quede puede esperar.","personality_tags":["velocista"]},{"id":"c","text":"Cero pendientes: hay gente esperando mi respuesta.","personality_tags":["colaborador"]},{"id":"d","text":"Contestada, con cada detalle confirmado.","personality_tags":["perfeccionista"]}],"explanation":null,"time_limit_seconds":30},{"id":"q5","question":"El plan de un compañero tiene una falla. Tú:","options":[{"id":"a","text":"Muestro cómo afecta el panorama completo.","personality_tags":["estratega"]},{"id":"b","text":"Lo corrijo sobre la marcha y sigo avanzando.","personality_tags":["velocista"]},{"id":"c","text":"Hago preguntas hasta que la detecte por su cuenta.","personality_tags":["colaborador"]},{"id":"d","text":"Envío notas detalladas con la corrección.","personality_tags":["perfeccionista"]}],"explanation":null,"time_limit_seconds":30},{"id":"q6","question":"Tu escritorio dice:","options":[{"id":"a","text":"Ordenado por etapas del proyecto.","personality_tags":["estratega"]},{"id":"b","text":"Caos creativo con un sistema que solo yo entiendo.","personality_tags":["velocista"]},{"id":"c","text":"Lleno de notas de peticiones de los demás.","personality_tags":["colaborador"]},{"id":"d","text":"Todo alineado, nada fuera de lugar.","personality_tags":["perfeccionista"]}],"explanation":null,"time_limit_seconds":30},{"id":"q7","question":"El elogio que de verdad disfrutas:","options":[{"id":"a","text":"''Ese plan nos ahorró un mes.''","personality_tags":["estratega"]},{"id":"b","text":"''¿Cómo terminaste eso tan rápido?''","personality_tags":["velocista"]},{"id":"c","text":"''El equipo funciona mejor cuando estás tú.''","personality_tags":["colaborador"]},{"id":"d","text":"''A tu trabajo nadie lo revisa dos veces.''","personality_tags":["perfeccionista"]}],"explanation":null,"time_limit_seconds":30},{"id":"q8","question":"Viernes por la tarde, proyecto entregado. Tú:","options":[{"id":"a","text":"Reviso qué acertó y qué falló el plan.","personality_tags":["estratega"]},{"id":"b","text":"Ya pienso en la racha del lunes.","personality_tags":["velocista"]},{"id":"c","text":"Invito al equipo a celebrar.","personality_tags":["colaborador"]},{"id":"d","text":"Doy una última pasada a la documentación.","personality_tags":["perfeccionista"]}],"explanation":null,"time_limit_seconds":30}]'::jsonb,
  '[{"id":"r1","title":"El Estratega","description":"Ves el tablero completo mientras otros ven la siguiente jugada. Tus planes ahorran más tiempo que cualquier carrera.","personality_tag":"estratega","background_theme":"stars"},{"id":"r2","title":"El Sprinter","description":"Las fechas límite son tu combustible. Mientras otros planean, tú ya entregaste y sigues adelante.","personality_tag":"velocista","background_theme":"fire"},{"id":"r3","title":"El Colaborador","description":"Haces que los equipos funcionen. Las reuniones se acortan y todos trabajan mejor cuando estás cerca.","personality_tag":"colaborador","background_theme":"ocean"},{"id":"r4","title":"El Perfeccionista","description":"Tu trabajo no vuelve con correcciones. Los detalles que se le escapan a todos son justo los que tú detectas.","personality_tag":"perfeccionista","background_theme":"ice"}]'::jsonb,
  array['personality quiz', 'trabajo', 'estilo de vida', 'evergreen']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-what-is-your-learning-style',
  'What Is Your Learning Style?',
  'Maps, lectures, manuals or bare hands — everyone has a shortcut into their own brain. Eight questions to find yours.',
  'personality',
  'easy',
  'en',
  (select id from public.categories where slug = 'culture'),
  '[{"id":"q1","question":"New software, no tutorial. You:","options":[{"id":"a","text":"Find a diagram of how it''s organized.","personality_tags":["visual"]},{"id":"b","text":"Watch a video of someone talking through it.","personality_tags":["auditory"]},{"id":"c","text":"Open the documentation at page one.","personality_tags":["reader"]},{"id":"d","text":"Click everything until it makes sense.","personality_tags":["hands_on"]}],"explanation":null,"time_limit_seconds":30},{"id":"q2","question":"The best class you ever took had:","options":[{"id":"a","text":"A whiteboard full of diagrams.","personality_tags":["visual"]},{"id":"b","text":"A teacher who told great stories.","personality_tags":["auditory"]},{"id":"c","text":"A reading list you still keep.","personality_tags":["reader"]},{"id":"d","text":"Labs where you built the actual thing.","personality_tags":["hands_on"]}],"explanation":null,"time_limit_seconds":30},{"id":"q3","question":"You need to remember a phone number for ten seconds. You:","options":[{"id":"a","text":"Picture the pattern on the keypad.","personality_tags":["visual"]},{"id":"b","text":"Repeat it out loud.","personality_tags":["auditory"]},{"id":"c","text":"Write it down instantly.","personality_tags":["reader"]},{"id":"d","text":"Type it with my fingers in the air.","personality_tags":["hands_on"]}],"explanation":null,"time_limit_seconds":30},{"id":"q4","question":"Directions to a new place:","options":[{"id":"a","text":"Show me the map.","personality_tags":["visual"]},{"id":"b","text":"Tell me the turns and the landmarks.","personality_tags":["auditory"]},{"id":"c","text":"Send me the written steps.","personality_tags":["reader"]},{"id":"d","text":"I''ll drive it once and never forget it.","personality_tags":["hands_on"]}],"explanation":null,"time_limit_seconds":30},{"id":"q5","question":"Your notes look like:","options":[{"id":"a","text":"Arrows, boxes and colors everywhere.","personality_tags":["visual"]},{"id":"b","text":"Sparse — the lecture is still in my head.","personality_tags":["auditory"]},{"id":"c","text":"Neat outlines with complete sentences.","personality_tags":["reader"]},{"id":"d","text":"Scribbles on whatever I was building.","personality_tags":["hands_on"]}],"explanation":null,"time_limit_seconds":30},{"id":"q6","question":"Learning to cook a new dish, you:","options":[{"id":"a","text":"Study the step-by-step photos.","personality_tags":["visual"]},{"id":"b","text":"Have someone talk me through it.","personality_tags":["auditory"]},{"id":"c","text":"Read the recipe twice, then start.","personality_tags":["reader"]},{"id":"d","text":"Start chopping and adjust as I go.","personality_tags":["hands_on"]}],"explanation":null,"time_limit_seconds":30},{"id":"q7","question":"The thing you learn fastest:","options":[{"id":"a","text":"Anything with charts and visuals.","personality_tags":["visual"]},{"id":"b","text":"Languages, by listening.","personality_tags":["auditory"]},{"id":"c","text":"History, through books.","personality_tags":["reader"]},{"id":"d","text":"Anything I can take apart.","personality_tags":["hands_on"]}],"explanation":null,"time_limit_seconds":30},{"id":"q8","question":"After a long study session, what stuck is:","options":[{"id":"a","text":"The image of the page or the diagram.","personality_tags":["visual"]},{"id":"b","text":"The explanation, almost word for word.","personality_tags":["auditory"]},{"id":"c","text":"The notes I wrote.","personality_tags":["reader"]},{"id":"d","text":"Whatever I practiced with my hands.","personality_tags":["hands_on"]}],"explanation":null,"time_limit_seconds":30}]'::jsonb,
  '[{"id":"r1","title":"The Visual Learner","description":"You think in pictures. A good diagram teaches you more in a minute than a chapter does in an hour.","personality_tag":"visual","background_theme":"stars"},{"id":"r2","title":"The Auditory Learner","description":"You learn by listening. Explain it out loud once and it''s yours forever.","personality_tag":"auditory","background_theme":"ocean"},{"id":"r3","title":"The Reader","description":"Give you a good text and you''ll teach yourself anything. Your notes are basically textbooks.","personality_tag":"reader","background_theme":"forest"},{"id":"r4","title":"The Hands-On Learner","description":"You learn by doing, breaking and rebuilding. The manual is a last resort, not a starting point.","personality_tag":"hands_on","background_theme":"fire"}]'::jsonb,
  array['personality quiz', 'learning', 'education', 'evergreen']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-cual-es-tu-estilo-de-aprendizaje',
  '¿Cuál Es Tu Estilo de Aprendizaje?',
  'Mapas, clases, manuales o las manos desnudas: todos tenemos un atajo hacia nuestro propio cerebro. Ocho preguntas para encontrar el tuyo.',
  'personality',
  'easy',
  'es',
  (select id from public.categories where slug = 'culture'),
  '[{"id":"q1","question":"Software nuevo, sin tutorial. Tú:","options":[{"id":"a","text":"Busco un diagrama de cómo está organizado.","personality_tags":["visual"]},{"id":"b","text":"Veo un video donde alguien lo explica.","personality_tags":["auditivo"]},{"id":"c","text":"Abro la documentación por la página uno.","personality_tags":["lector"]},{"id":"d","text":"Hago clic en todo hasta entenderlo.","personality_tags":["practico"]}],"explanation":null,"time_limit_seconds":30},{"id":"q2","question":"La mejor clase que tomaste tenía:","options":[{"id":"a","text":"Una pizarra llena de diagramas.","personality_tags":["visual"]},{"id":"b","text":"Un profesor que contaba grandes historias.","personality_tags":["auditivo"]},{"id":"c","text":"Una lista de lecturas que aún conservas.","personality_tags":["lector"]},{"id":"d","text":"Prácticas donde construías la cosa de verdad.","personality_tags":["practico"]}],"explanation":null,"time_limit_seconds":30},{"id":"q3","question":"Debes recordar un número de teléfono por diez segundos. Tú:","options":[{"id":"a","text":"Me imagino el patrón en el teclado.","personality_tags":["visual"]},{"id":"b","text":"Lo repito en voz alta.","personality_tags":["auditivo"]},{"id":"c","text":"Lo escribo de inmediato.","personality_tags":["lector"]},{"id":"d","text":"Lo tecleo con los dedos en el aire.","personality_tags":["practico"]}],"explanation":null,"time_limit_seconds":30},{"id":"q4","question":"Indicaciones para llegar a un lugar nuevo:","options":[{"id":"a","text":"Muéstrame el mapa.","personality_tags":["visual"]},{"id":"b","text":"Dime los giros y las referencias.","personality_tags":["auditivo"]},{"id":"c","text":"Mándame los pasos por escrito.","personality_tags":["lector"]},{"id":"d","text":"Lo recorro una vez y no lo olvido.","personality_tags":["practico"]}],"explanation":null,"time_limit_seconds":30},{"id":"q5","question":"Tus apuntes se ven así:","options":[{"id":"a","text":"Flechas, recuadros y colores por todas partes.","personality_tags":["visual"]},{"id":"b","text":"Escasos: la explicación sigue en mi cabeza.","personality_tags":["auditivo"]},{"id":"c","text":"Esquemas ordenados con frases completas.","personality_tags":["lector"]},{"id":"d","text":"Garabatos sobre lo que estaba armando.","personality_tags":["practico"]}],"explanation":null,"time_limit_seconds":30},{"id":"q6","question":"Para aprender a cocinar un plato nuevo, tú:","options":[{"id":"a","text":"Estudio las fotos paso a paso.","personality_tags":["visual"]},{"id":"b","text":"Pido que alguien me lo explique en voz alta.","personality_tags":["auditivo"]},{"id":"c","text":"Leo la receta dos veces y empiezo.","personality_tags":["lector"]},{"id":"d","text":"Empiezo a picar y ajusto sobre la marcha.","personality_tags":["practico"]}],"explanation":null,"time_limit_seconds":30},{"id":"q7","question":"Lo que aprendes más rápido:","options":[{"id":"a","text":"Todo lo que tenga gráficos e imágenes.","personality_tags":["visual"]},{"id":"b","text":"Idiomas, escuchando.","personality_tags":["auditivo"]},{"id":"c","text":"Historia, a través de libros.","personality_tags":["lector"]},{"id":"d","text":"Cualquier cosa que pueda desarmar.","personality_tags":["practico"]}],"explanation":null,"time_limit_seconds":30},{"id":"q8","question":"Tras una sesión larga de estudio, lo que queda es:","options":[{"id":"a","text":"La imagen de la página o del diagrama.","personality_tags":["visual"]},{"id":"b","text":"La explicación, casi palabra por palabra.","personality_tags":["auditivo"]},{"id":"c","text":"Los apuntes que escribí.","personality_tags":["lector"]},{"id":"d","text":"Lo que practiqué con las manos.","personality_tags":["practico"]}],"explanation":null,"time_limit_seconds":30}]'::jsonb,
  '[{"id":"r1","title":"El Visual","description":"Piensas en imágenes. Un buen diagrama te enseña en un minuto lo que un capítulo no logra en una hora.","personality_tag":"visual","background_theme":"stars"},{"id":"r2","title":"El Auditivo","description":"Aprendes escuchando. Que te lo expliquen en voz alta una vez y es tuyo para siempre.","personality_tag":"auditivo","background_theme":"ocean"},{"id":"r3","title":"El Lector","description":"Con un buen texto te enseñas lo que sea por tu cuenta. Tus apuntes son prácticamente libros de texto.","personality_tag":"lector","background_theme":"forest"},{"id":"r4","title":"El Práctico","description":"Aprendes haciendo, rompiendo y reconstruyendo. El manual es el último recurso, no el punto de partida.","personality_tag":"practico","background_theme":"fire"}]'::jsonb,
  array['personality quiz', 'aprendizaje', 'educacion', 'evergreen']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-what-is-your-ideal-weekend',
  'What Is Your Ideal Weekend?',
  'Two free days say everything. Trails, couches, crowded tables or a full workshop — pick your perfect 48 hours.',
  'personality',
  'easy',
  'en',
  (select id from public.categories where slug = 'lifestyle'),
  '[{"id":"q1","question":"Friday night, no plans. You:","options":[{"id":"a","text":"Check the forecast for Saturday''s trail.","personality_tags":["adventurer"]},{"id":"b","text":"Cook something slow and start a new series.","personality_tags":["homebody"]},{"id":"c","text":"Text the group: ''Who''s out tonight?''","personality_tags":["social"]},{"id":"d","text":"Finally open the project I''ve been sketching all week.","personality_tags":["creator"]}],"explanation":null,"time_limit_seconds":30},{"id":"q2","question":"Saturday morning, ideally:","options":[{"id":"a","text":"Somewhere I''ve never been, before sunrise.","personality_tags":["adventurer"]},{"id":"b","text":"Coffee in bed, nowhere to be.","personality_tags":["homebody"]},{"id":"c","text":"A long brunch with people I like.","personality_tags":["social"]},{"id":"d","text":"A few uninterrupted hours at the workbench.","personality_tags":["creator"]}],"explanation":null,"time_limit_seconds":30},{"id":"q3","question":"The perfect Sunday ends with:","options":[{"id":"a","text":"Tired legs and photos worth keeping.","personality_tags":["adventurer"]},{"id":"b","text":"Clean sheets and an early night.","personality_tags":["homebody"]},{"id":"c","text":"One more round before everyone leaves.","personality_tags":["social"]},{"id":"d","text":"Something finished that didn''t exist on Friday.","personality_tags":["creator"]}],"explanation":null,"time_limit_seconds":30},{"id":"q4","question":"A free weekend gift card — you spend it on:","options":[{"id":"a","text":"Gear for the next trip.","personality_tags":["adventurer"]},{"id":"b","text":"Good ingredients and a better blanket.","personality_tags":["homebody"]},{"id":"c","text":"Tickets for everyone.","personality_tags":["social"]},{"id":"d","text":"Materials, tools, maybe a class.","personality_tags":["creator"]}],"explanation":null,"time_limit_seconds":30},{"id":"q5","question":"Rain all weekend. You:","options":[{"id":"a","text":"Go anyway — waterproof is a personality trait.","personality_tags":["adventurer"]},{"id":"b","text":"Secretly thrilled. The couch wins.","personality_tags":["homebody"]},{"id":"c","text":"Move the plan indoors; the people are the plan.","personality_tags":["social"]},{"id":"d","text":"Perfect — a whole weekend in the workshop.","personality_tags":["creator"]}],"explanation":null,"time_limit_seconds":30},{"id":"q6","question":"Monday''s ''so what did you do?'' answer:","options":[{"id":"a","text":"A place name they''ve never heard of.","personality_tags":["adventurer"]},{"id":"b","text":"''Nothing,'' said with great satisfaction.","personality_tags":["homebody"]},{"id":"c","text":"A story with at least four people in it.","personality_tags":["social"]},{"id":"d","text":"''Made this'' — and I show them.","personality_tags":["creator"]}],"explanation":null,"time_limit_seconds":30},{"id":"q7","question":"Your ideal weekend companion:","options":[{"id":"a","text":"Someone who''ll say yes to the detour.","personality_tags":["adventurer"]},{"id":"b","text":"A pet, a blanket, maybe nobody.","personality_tags":["homebody"]},{"id":"c","text":"Everyone. The more the better.","personality_tags":["social"]},{"id":"d","text":"Someone who''ll hand me the right tool.","personality_tags":["creator"]}],"explanation":null,"time_limit_seconds":30},{"id":"q8","question":"The weekend you brag about involved:","options":[{"id":"a","text":"Altitude, distance, or both.","personality_tags":["adventurer"]},{"id":"b","text":"Absolutely nobody knowing where I was.","personality_tags":["homebody"]},{"id":"c","text":"The party people still talk about.","personality_tags":["social"]},{"id":"d","text":"A thing I built with my own hands.","personality_tags":["creator"]}],"explanation":null,"time_limit_seconds":30}]'::jsonb,
  '[{"id":"r1","title":"The Adventurer","description":"A weekend only counts if it takes you somewhere. Mud, altitude and questionable weather are all acceptable.","personality_tag":"adventurer","background_theme":"forest"},{"id":"r2","title":"The Homebody","description":"The best plan is no plan. You''ve perfected the art of doing nothing and you''re not apologizing for it.","personality_tag":"homebody","background_theme":"ice"},{"id":"r3","title":"The Socializer","description":"Weekends are for people. You''d rather have a mediocre plan with great company than the reverse.","personality_tag":"social","background_theme":"fire"},{"id":"r4","title":"The Creator","description":"Your weekends produce things. While others rest, you make — and Monday arrives with proof.","personality_tag":"creator","background_theme":"mystic"}]'::jsonb,
  array['personality quiz', 'weekend', 'lifestyle', 'evergreen']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-cual-es-tu-fin-de-semana-ideal',
  '¿Cuál Es Tu Fin de Semana Ideal?',
  'Dos días libres lo dicen todo. Senderos, sofá, mesas llenas o un taller completo: elige tus 48 horas perfectas.',
  'personality',
  'easy',
  'es',
  (select id from public.categories where slug = 'lifestyle'),
  '[{"id":"q1","question":"Viernes por la noche, sin planes. Tú:","options":[{"id":"a","text":"Reviso el clima para la ruta del sábado.","personality_tags":["aventurero"]},{"id":"b","text":"Cocino algo lento y empiezo una serie nueva.","personality_tags":["hogareno"]},{"id":"c","text":"Escribo al grupo: ''¿Quién sale esta noche?''","personality_tags":["sociable"]},{"id":"d","text":"Por fin abro el proyecto que llevo semanas imaginando.","personality_tags":["creativo"]}],"explanation":null,"time_limit_seconds":30},{"id":"q2","question":"Sábado por la mañana, idealmente:","options":[{"id":"a","text":"En un lugar donde nunca estuve, antes del amanecer.","personality_tags":["aventurero"]},{"id":"b","text":"Café en la cama, sin ningún compromiso.","personality_tags":["hogareno"]},{"id":"c","text":"Un brunch largo con gente que me gusta.","personality_tags":["sociable"]},{"id":"d","text":"Unas horas sin interrupciones en mi taller.","personality_tags":["creativo"]}],"explanation":null,"time_limit_seconds":30},{"id":"q3","question":"El domingo perfecto termina con:","options":[{"id":"a","text":"Piernas cansadas y fotos que valen la pena.","personality_tags":["aventurero"]},{"id":"b","text":"Sábanas limpias y dormir temprano.","personality_tags":["hogareno"]},{"id":"c","text":"Una última ronda antes de que todos se vayan.","personality_tags":["sociable"]},{"id":"d","text":"Algo terminado que el viernes no existía.","personality_tags":["creativo"]}],"explanation":null,"time_limit_seconds":30},{"id":"q4","question":"Te regalan una tarjeta para el fin de semana. La gastas en:","options":[{"id":"a","text":"Equipo para el próximo viaje.","personality_tags":["aventurero"]},{"id":"b","text":"Buenos ingredientes y una manta mejor.","personality_tags":["hogareno"]},{"id":"c","text":"Entradas para todos.","personality_tags":["sociable"]},{"id":"d","text":"Materiales, herramientas, quizás un curso.","personality_tags":["creativo"]}],"explanation":null,"time_limit_seconds":30},{"id":"q5","question":"Lluvia todo el fin de semana. Tú:","options":[{"id":"a","text":"Salgo igual: lo impermeable es una forma de ser.","personality_tags":["aventurero"]},{"id":"b","text":"En secreto, feliz. El sofá gana.","personality_tags":["hogareno"]},{"id":"c","text":"Traslado el plan adentro; el plan es la gente.","personality_tags":["sociable"]},{"id":"d","text":"Perfecto: un fin de semana entero en el taller.","personality_tags":["creativo"]}],"explanation":null,"time_limit_seconds":30},{"id":"q6","question":"El lunes preguntan ''¿qué hiciste?''. Tu respuesta:","options":[{"id":"a","text":"Un lugar del que nunca oyeron hablar.","personality_tags":["aventurero"]},{"id":"b","text":"''Nada'', dicho con gran satisfacción.","personality_tags":["hogareno"]},{"id":"c","text":"Una historia con al menos cuatro personas.","personality_tags":["sociable"]},{"id":"d","text":"''Hice esto'', y se lo muestro.","personality_tags":["creativo"]}],"explanation":null,"time_limit_seconds":30},{"id":"q7","question":"Tu compañía ideal de fin de semana:","options":[{"id":"a","text":"Alguien que diga sí al desvío.","personality_tags":["aventurero"]},{"id":"b","text":"Una mascota, una manta, quizás nadie.","personality_tags":["hogareno"]},{"id":"c","text":"Todos. Cuantos más, mejor.","personality_tags":["sociable"]},{"id":"d","text":"Alguien que me pase la herramienta correcta.","personality_tags":["creativo"]}],"explanation":null,"time_limit_seconds":30},{"id":"q8","question":"El fin de semana del que presumes incluyó:","options":[{"id":"a","text":"Altura, distancia o ambas.","personality_tags":["aventurero"]},{"id":"b","text":"Que nadie supiera dónde estaba.","personality_tags":["hogareno"]},{"id":"c","text":"La fiesta de la que todos siguen hablando.","personality_tags":["sociable"]},{"id":"d","text":"Algo que construí con mis propias manos.","personality_tags":["creativo"]}],"explanation":null,"time_limit_seconds":30}]'::jsonb,
  '[{"id":"r1","title":"El Aventurero","description":"Un fin de semana solo cuenta si te lleva a algún lugar. Barro, altura y clima dudoso son aceptables.","personality_tag":"aventurero","background_theme":"forest"},{"id":"r2","title":"El Hogareño","description":"El mejor plan es no tener plan. Dominaste el arte de no hacer nada y no pides disculpas por ello.","personality_tag":"hogareno","background_theme":"ice"},{"id":"r3","title":"El Sociable","description":"Los fines de semana son para la gente. Prefieres un plan mediocre con buena compañía que lo contrario.","personality_tag":"sociable","background_theme":"fire"},{"id":"r4","title":"El Creativo","description":"Tus fines de semana producen cosas. Mientras otros descansan, tú creas, y el lunes llega con pruebas.","personality_tag":"creativo","background_theme":"mystic"}]'::jsonb,
